import { Equal, Expect } from "../helpers/type-utils";

const BACKEND_TO_FRONTEND_STATUS_MAP = {
  0: "pending",
  1: "success",
  2: "error",
} as const;

type BackendStatusMap = typeof BACKEND_TO_FRONTEND_STATUS_MAP;

type BackendStatus = keyof BackendStatusMap;
type FrontendStatus = BackendStatusMap[BackendStatus];

type test = [
  Expect<Equal<BackendStatus, 0 | 1 | 2>>,
  Expect<Equal<FrontendStatus, "pending" | "success" | "error">>
];

import { Equal, Expect } from "../helpers/type-utils";

/**
 * 1. We've got a bunch of different errors below. See if you can figure
 * out why the errors are happening.
 *
 * 2. Once you understand why the errors are happening, see if you can
 * find a way to fix them by changing the definition of TableProps.
 */
interface TableProps {
  renderRow: React.ReactNode;
}

const Table = (props: TableProps) => {
  return <div>{[0, 1, 3].map(props.renderRow)}</div>;
};

export const Parent = () => {
  return (
    <>
      <Table
        renderRow={(index) => {
          type test = Expect<Equal<typeof index, number>>;
          return <div key={index}>{index}</div>;
        }}
      />
      <Table
        renderRow={(index) => {
          return null;
        }}
      />
      <Table
        // @ts-expect-error
        renderRow={<div></div>}
      />
      <Table
        renderRow={(index) => {
          return index;
        }}
      />
    </>
  );
};

const presetSizes = {
  xs: "0.5rem",
  sm: "1rem",
};

type Size = keyof typeof presetSizes;

/**
 * Oddly, this works. Forcing string to intersect with {} does SOMETHING
 * which makes TypeScript do what we want.
 *
 * Honestly, I'm not sure why this works. Some compiler-diving is required
 * to figure it out.
 */
type LooseSize = Size | (string & {});

export const Icon = (props: { size: LooseSize }) => {
  return (
    <div
      style={{
        width:
          props.size in presetSizes
            ? presetSizes[props.size as Size]
            : props.size,
      }}
    />
  );
};

<>
  <Icon size="sm"></Icon>
  <Icon size="xs"></Icon>
  <Icon size="10px"></Icon>
</>;

type ModalProps =
  | {
      variant: "no-title";
    }
  | {
      variant: "title";
      title: string;
    };

/**
 * Sadly, this doesn't work - TypeScript can't figure out from narrowing
 * the destructured variant that the title is now available.
 */
export const Modal = ({ variant, ...props }: ModalProps) => {
  if (variant === "no-title") {
    return <div>No title</div>;
  } else {
    return <div>Title: {props.title}</div>;
  }
};

export const Test = () => {
  return (
    <div>
      <Modal variant="title" title="Hello" />
      <Modal variant="no-title" />

      {/* @ts-expect-error */}
      <Modal />
      <Modal
        variant="no-title"
        // @ts-expect-error
        title="Oh dear"
      />
    </div>
  );
};

